function buildRandomEliteAssign() {
  const teams = [...ELITE_IDS];
  for (let i = teams.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [teams[i], teams[j]] = [teams[j], teams[i]];
  }
  const out = {};
  PEOPLE.forEach((p, i) => { out[p] = teams[i]; });
  return out;
}

