function KnockoutCountdown({ kickoff }) {
  const [timeLeft, setTimeLeft] = React.useState("");
  React.useEffect(() => {
    const update = () => {
      const diff = new Date(kickoff) - new Date();
      if (diff <= 0) { setTimeLeft("LIVE / FINISHED"); return; }
      const h = Math.floor(diff / 3600000);
      const m = Math.floor((diff % 3600000) / 60000);
      setTimeLeft(h > 0 ? `${h}h ${m}m to kickoff` : `${m}m to kickoff`);
    };
    update();
    const t = setInterval(update, 60000);
    return () => clearInterval(t);
  }, [kickoff]);
  return <div className="ko-countdown">⏱ {timeLeft}</div>;
}

function BracketPicker({ matches, userId, existing, showToast }) {
  const sf1 = matches.find(m => m.id === "sf_01");
  const sf2 = matches.find(m => m.id === "sf_02");
  const teams = [];
  [sf1, sf2].forEach(sf => {
    if (sf) {
      if (sf.home && sf.home !== "tbd") teams.push(sf.home);
      if (sf.away && sf.away !== "tbd") teams.push(sf.away);
    }
  });
  const qfTeams = [];
  ["qf_01","qf_02","qf_03","qf_04"].forEach(id => {
    const m = matches.find(x => x.id === id);
    if (m) {
      if (m.home && m.home !== "tbd") qfTeams.push(m.home);
      if (m.away && m.away !== "tbd") qfTeams.push(m.away);
    }
  });
  const pickable = teams.length >= 2 ? teams : [...new Set(qfTeams)];
  const [f1, setF1] = React.useState(existing?.finalist_1 || null);
  const [f2, setF2] = React.useState(existing?.finalist_2 || null);
  const [saving, setSaving] = React.useState(false);
  const locked = existing?.locked || false;

  const handlePick = (team) => {
    if (locked) return;
    if (f1 === team) { setF1(null); return; }
    if (f2 === team) { setF2(null); return; }
    if (!f1) { setF1(team); return; }
    if (!f2) { setF2(team); return; }
    setF1(team); setF2(null);
  };

  const handleSave = async () => {
    if (!f1 || !f2) { showToast({ title: "⚠️ Pick both finalists!" }); return; }
    setSaving(true);
    await sbUpsert("special_predictions", {
      id: userId + "_bracket",
      user_id: userId,
      match_id: "final_01",
      prediction_type: "bracket",
      finalist_1: f1,
      finalist_2: f2,
      locked: true,
      created_at: new Date().toISOString(),
    });
    showToast({ title: "✅ Bracket saved!" });
    setSaving(false);
  };

  if (pickable.length === 0) return (
    <div className="ko-empty">
      <div className="ko-empty-icon">⏳</div>
      <div className="ko-empty-title">Teams Not Confirmed Yet</div>
      <div className="ko-empty-sub">Check back once Quarter Finals are done</div>
    </div>
  );

  return (
    <div>
      <div className="ko-section-sub">Pick the two teams you think will contest the Final. 100pts for both correct · 50pts for one.</div>
      <div className="ko-bracket-grid">
        {pickable.map(team => {
          const sel = f1 === team || f2 === team;
          return (
            <div key={team} className={"ko-finalist-pick" + (sel ? " selected" : "")} onClick={() => handlePick(team)}>
              <Flag code={team} size={40} />
              <div className="ko-finalist-name">{team.toUpperCase()}</div>
              {f1 === team && <div style={{ fontSize: 10, color: "var(--teal)", fontWeight: 800, marginTop: 4 }}>FINALIST 1 ✓</div>}
              {f2 === team && <div style={{ fontSize: 10, color: "var(--teal)", fontWeight: 800, marginTop: 4 }}>FINALIST 2 ✓</div>}
            </div>
          );
        })}
      </div>
      {f1 && f2 && (
        <div style={{ background: "rgba(0,191,165,.08)", borderRadius: 12, padding: "10px 14px", marginBottom: 14, textAlign: "center" }}>
          <span style={{ fontSize: 13, fontWeight: 800, color: "var(--teal)" }}>
            Your Final: <Flag code={f1} size={20} style={{ marginRight: 4 }} /> {f1.toUpperCase()} vs <Flag code={f2} size={20} style={{ marginLeft: 4, marginRight: 4 }} /> {f2.toUpperCase()}
          </span>
        </div>
      )}
      {locked
        ? <div className="ko-locked">🔒 Bracket locked — good luck!</div>
        : <button className="ko-submit-btn" onClick={handleSave} disabled={saving || !f1 || !f2}>{saving ? "SAVING..." : "🔒 LOCK MY BRACKET"}</button>
      }
    </div>
  );
}

function GoldenTicketCard({ match, userId, existing, showToast, label }) {
  const homeId = match?.home || "tbd";
  const awayId = match?.away || "tbd";
  const home = homeId.toUpperCase();
  const away = awayId.toUpperCase();
  const isLocked = match?.status === "completed" || existing?.locked;
  const kickoff = match?.kickoff;
  const isBeforeKickoff = kickoff ? new Date() < new Date(kickoff) : true;
  const [homeScore, setHomeScore] = React.useState(existing?.home_score ?? 1);
  const [awayScore, setAwayScore] = React.useState(existing?.away_score ?? 1);
  const [scorer, setScorer] = React.useState(existing?.first_scoring_team || null);
  const [penalties, setPenalties] = React.useState(existing?.goes_to_extra_time ?? false);
  const [saving, setSaving] = React.useState(false);

  const handleSave = async () => {
    if (!match?.id) return;
    setSaving(true);
    await sbUpsert("special_predictions", {
      id: userId + "_" + match.id,
      user_id: userId,
      match_id: match.id,
      prediction_type: "golden_ticket",
      home_score: homeScore,
      away_score: awayScore,
      first_scoring_team: scorer,
      goes_to_extra_time: penalties,
      locked: true,
      created_at: new Date().toISOString(),
    });
    showToast({ title: "✅ Golden Ticket saved!" });
    setSaving(false);
  };

  if (homeId === "tbd" || awayId === "tbd") return (
    <div className="ko-empty" style={{ padding: "28px 20px" }}>
      <div style={{ fontSize: 36, marginBottom: 8 }}>⏳</div>
      <div style={{ fontWeight: 800, color: "var(--navy)", marginBottom: 4 }}>{label} — Teams TBD</div>
      <div style={{ fontSize: 12, color: "var(--muted)", fontWeight: 600 }}>Available once both teams are confirmed</div>
    </div>
  );

  return (
    <div>
      {kickoff && isBeforeKickoff && <KnockoutCountdown kickoff={kickoff} />}
      <div className="ko-match-header">
        <div style={{ textAlign: "center" }}>
          <Flag code={homeId} size={40} />
          <div className="ko-team-name">{home}</div>
        </div>
        <div className="ko-vs">VS</div>
        <div style={{ textAlign: "center" }}>
          <Flag code={awayId} size={40} />
          <div className="ko-team-name">{away}</div>
        </div>
      </div>
      <span className="ko-label">Predict the Scoreline <span style={{ color: "var(--yellow)" }}>+30pts</span></span>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 16, marginBottom: 16 }}>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
          <Flag code={homeId} size={24} />
          <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
            <button className="ko-score-btn" onClick={() => !isLocked && setHomeScore(Math.max(0, homeScore - 1))} disabled={isLocked}>−</button>
            <div className="ko-score-display">{homeScore}</div>
            <button className="ko-score-btn" onClick={() => !isLocked && setHomeScore(Math.min(9, homeScore + 1))} disabled={isLocked}>+</button>
          </div>
        </div>
        <div className="ko-score-sep">–</div>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
          <Flag code={awayId} size={24} />
          <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
            <button className="ko-score-btn" onClick={() => !isLocked && setAwayScore(Math.max(0, awayScore - 1))} disabled={isLocked}>−</button>
            <div className="ko-score-display">{awayScore}</div>
            <button className="ko-score-btn" onClick={() => !isLocked && setAwayScore(Math.min(9, awayScore + 1))} disabled={isLocked}>+</button>
          </div>
        </div>
      </div>
      <span className="ko-label">First Team to Score <span style={{ color: "var(--yellow)" }}>+20pts</span></span>
      <div className="ko-toggle">
        <button className={"ko-toggle-btn" + (scorer === homeId ? " on" : "")} onClick={() => !isLocked && setScorer(homeId)} disabled={isLocked}>
          <Flag code={homeId} size={18} style={{ marginRight: 6 }} /> {home}
        </button>
        <button className={"ko-toggle-btn" + (scorer === awayId ? " on" : "")} onClick={() => !isLocked && setScorer(awayId)} disabled={isLocked}>
          <Flag code={awayId} size={18} style={{ marginRight: 6 }} /> {away}
        </button>
      </div>
      <span className="ko-label">Goes to Extra Time / Penalties? <span style={{ color: "var(--yellow)" }}>+20pts</span></span>
      <div className="ko-toggle">
        <button className={"ko-toggle-btn" + (!penalties ? " on" : "")} onClick={() => !isLocked && setPenalties(false)} disabled={isLocked}>⚽ No — Normal Time</button>
        <button className={"ko-toggle-btn" + (penalties ? " on" : "")} onClick={() => !isLocked && setPenalties(true)} disabled={isLocked}>🥊 Yes — Extra Time / Pens</button>
      </div>
      {isLocked
        ? <div className="ko-locked">🔒 Prediction locked — fingers crossed! Max 70pts available.</div>
        : <button className="ko-submit-btn" onClick={handleSave} disabled={saving}>{saving ? "SAVING..." : "🎯 LOCK GOLDEN TICKET"}</button>
      }
      {existing && (
        <div style={{ marginTop: 14 }}>
          <div className="ko-divider" />
          <div style={{ fontSize: 12, fontWeight: 800, color: "var(--muted)", marginBottom: 8 }}>YOUR SAVED PREDICTION</div>
          <div className="ko-result-row"><span className="ko-result-label">Score</span><span className="ko-result-value">{home} {existing.home_score} – {existing.away_score} {away}</span></div>
          <div className="ko-result-row">
            <span className="ko-result-label">First Team to Score</span>
            <span className="ko-result-value" style={{ display: "flex", alignItems: "center", gap: 6 }}>
              {existing.first_scoring_team
                ? <><Flag code={existing.first_scoring_team} size={18} /> {existing.first_scoring_team.toUpperCase()}</>
                : "—"}
            </span>
          </div>
          <div className="ko-result-row"><span className="ko-result-label">Extra Time / Pens</span><span className="ko-result-value">{existing.goes_to_extra_time ? "Yes" : "No"}</span></div>
        </div>
      )}
    </div>
  );
}

function Knockout({ user, matches, participants, showToast }) {
  const userId = user?.toLowerCase();
  const [activeTab, setActiveTab] = React.useState("bracket");
  const [specialPreds, setSpecialPreds] = React.useState([]);
  const [koLoading, setKoLoading] = React.useState(true);

  React.useEffect(() => {
    const load = async () => {
      if (!userId) return;
      const data = await sbGet("special_predictions", "user_id=eq." + userId);
      setSpecialPreds(data || []);
      setKoLoading(false);
    };
    load();
  }, [userId]);

  const getPred = (matchId) => specialPreds.find(p => p.match_id === matchId && p.prediction_type === "golden_ticket");
  const getBracketPred = () => specialPreds.find(p => p.prediction_type === "bracket");

  const sf1 = matches.find(m => m.id === "sf_01");
  const sf2 = matches.find(m => m.id === "sf_02");
  const final = matches.find(m => m.id === "final_01");

  const tabs = [
    { id: "bracket", label: "🎯 Final Bracket" },
    { id: "sf1",     label: "⚽ Semi Final 1"  },
    { id: "sf2",     label: "⚽ Semi Final 2"  },
    { id: "final",   label: "🏆 The Final"      },
  ];

  return (
    <div>
      <style>{KNOCKOUT_CSS}</style>
      <div className="phead">
        <div className="ptitle">⭐ Glory Road</div>
        <div className="psub">Semi Finals · Final · Special Predictions — up to 310 bonus points</div>
      </div>
      <div className="ko-hero">
        <div className="ko-hero-title">THE BUSINESS END</div>
        <div className="ko-hero-sub">Every prediction counts more from here. Pick your finalists, nail the scoreline, call which team scores first.</div>
        <div className="ko-pts-pill">⭐ Up to 310 bonus points available</div>
      </div>
      <div className="ko-tab-row">
        {tabs.map(t => (
          <div key={t.id} className={"ko-tab" + (activeTab === t.id ? " on" : "")} onClick={() => setActiveTab(t.id)}>{t.label}</div>
        ))}
      </div>

      {activeTab === "bracket" && (
        <div className="ko-section">
          <div className="ko-section-title">🎯 Perfect Final Bracket</div>
          <BracketPicker matches={matches} userId={userId} existing={getBracketPred()} showToast={showToast} />
        </div>
      )}
      {activeTab === "sf1" && (
        <div className="ko-section">
          <div className="ko-section-title">⚽ Semi Final 1 — Golden Ticket</div>
          <div style={{ fontSize: 11, color: "var(--muted)", fontWeight: 700, marginBottom: 14 }}>Max 70pts · Score +30 · First Team to Score +20 · Pens/ET +20</div>
          {koLoading ? <div style={{ color: "var(--muted)", textAlign: "center", padding: 20 }}>Loading...</div>
            : <GoldenTicketCard match={sf1} userId={userId} existing={getPred("sf_01")} showToast={showToast} label="Semi Final 1" />}
        </div>
      )}
      {activeTab === "sf2" && (
        <div className="ko-section">
          <div className="ko-section-title">⚽ Semi Final 2 — Golden Ticket</div>
          <div style={{ fontSize: 11, color: "var(--muted)", fontWeight: 700, marginBottom: 14 }}>Max 70pts · Score +30 · First Team to Score +20 · Pens/ET +20</div>
          {koLoading ? <div style={{ color: "var(--muted)", textAlign: "center", padding: 20 }}>Loading...</div>
            : <GoldenTicketCard match={sf2} userId={userId} existing={getPred("sf_02")} showToast={showToast} label="Semi Final 2" />}
        </div>
      )}
      {activeTab === "final" && (
        <div className="ko-section">
          <div className="ko-section-title">🏆 The Final — Golden Ticket</div>
          <div style={{ fontSize: 11, color: "var(--muted)", fontWeight: 700, marginBottom: 14 }}>Max 70pts · Score +30 · First Team to Score +20 · Pens/ET +20</div>
          {koLoading ? <div style={{ color: "var(--muted)", textAlign: "center", padding: 20 }}>Loading...</div>
            : <GoldenTicketCard match={final} userId={userId} existing={getPred("final_01")} showToast={showToast} label="The Final" />}
        </div>
      )}
    </div>
  );
}

// ─── APP ROOT ────────────────────────────────────────────────────
export default function App() {
  const [page,         setPage]        = useState("dashboard");
  const [currentUser,  setCurrentUser] = useState(null);
  const [loading,      setLoading]     = useState(true);
  const [showHowTo,    setShowHowTo]   = useState(() => {
    try { return !localStorage.getItem("wc2026_howto_seen"); } catch(e) { return true; }
  });
  const [toast,        setToast]       = useState(null);
  const [participants, setParticipants]= useState(PEOPLE.map(name => ({ name, teamPts: 0, predPts: 0, challengePts: 0, bonusPts: 0, gloryRoadPts: 0, portfolio: [] })));
  const [matches,      setMatches]     = useState([]);
  const [predictions,  setPredictions] = useState({});
  const [claimedTeams, setClaimedTeams]= useState({ contenders: [], underdogs: [] });
  const [eliteAssign,  setEliteAssign] = useState(null);

  const showToast = msg => setToast(msg);
  const isAdmin   = currentUser === "Brandon" || currentUser === "Cherine";

  // ── LOAD ALL DATA FROM SUPABASE ───────────────────────────────
  useEffect(() => {
    async function boot() {
      setLoading(true);
      try {
        // 1. Load participants
        const dbP = await sbGet("participants");
        if (dbP && dbP.length > 0) {
          const merged = PEOPLE.map(name => {
            // Match by both id (lowercase) and name to handle inconsistency
            const db = dbP.find(d => d && (d.name === name || d.id === name.toLowerCase()));
            return db
              ? { name, teamPts: db.team_pts || 0, predPts: db.pred_pts || 0, challengePts: db.challenge_pts || 0, bonusPts: db.bonus_pts || 0, gloryRoadPts: db.glory_road_pts || 0, portfolio: [] }
              : { name, teamPts: 0, predPts: 0, challengePts: 0, bonusPts: 0, gloryRoadPts: 0, portfolio: [] };
          });
          setParticipants(merged);
        }

        // 2. Load matches
        const dbM = await sbGet("matches", "order=kickoff.asc");
        if (dbM && dbM.length > 0) {
          setMatches(dbM.filter(m => m && m.id).map(m => ({
            id:        m.id,
            home:      m.home_id    || "tbd",
            away:      m.away_id    || "tbd",
            stage:     m.stage      || "Group Stage",
            date:      m.match_date || "",
            kickoff:   m.kickoff    || null,
            status:    m.status     || "open",
            homeScore: m.home_score != null ? m.home_score : null,
            awayScore: m.away_score != null ? m.away_score : null,
            notes:     m.notes      || null,
            winner:    m.winner     || null,
          })));
        }

        // 3. Load or create elite assignment
        const dbE = await sbGet("elite_assign", "id=eq.1");
        if (dbE && dbE.length > 0) {
          setEliteAssign(dbE[0].assignment);
        } else {
          const fresh = buildRandomEliteAssign();
          await sbUpsert("elite_assign", { id: 1, assignment: fresh });
          setEliteAssign(fresh);
        }

        // 4. Load portfolios
        const dbPort = await sbGet("portfolios");
        if (dbPort && dbPort.length > 0) {
          const contenders = dbPort.filter(p => p && p.slot_type === "contender").map(p => p.team_id);
          const underdogs  = dbPort.filter(p => p && p.slot_type === "underdog").map(p => p.team_id);
          setClaimedTeams({ contenders, underdogs });
          setParticipants(prev => prev.map(p => ({
            ...p,
            portfolio: dbPort.filter(pt => pt && pt.user_id === p.name.toLowerCase()).map(pt => ({
              team: pt.team_id,
              slot: pt.slot_type,
              stage: pt.current_stage || "Group Stage",
              won: pt.won_stages || [],
              eliminated: pt.eliminated || false,
            })),
          })));
        }

        // Session restore handled by name picker

        // 6. Load challenge completions (persists which challenges are done)
        // We load for all users and store keyed by user so Challenge component can read
        const dbAllComp = await sbGet("challenge_completions");
        if (dbAllComp && dbAllComp.length > 0) {
          // Store in a ref accessible to Challenge — grouped by user
          const compByUser = {};
          dbAllComp.forEach(c => {
            if (!compByUser[c.user_id]) compByUser[c.user_id] = {};
            compByUser[c.user_id]["w" + c.week + "_" + c.challenge_id] = c.pts_earned;
          });
          sessionStorage.setItem("wc2026_completions", JSON.stringify(compByUser));
        }

      } catch(e) {
        console.error("Boot error:", e);
      }
      setLoading(false);
    }
    boot();
  }, []);

  // ── POLL FOR UPDATES EVERY 10 SECONDS ────────────────────────
  useEffect(() => {
    const poll = async () => {
      try {
        // Always poll participants and portfolios (needed for name picker too)
        const dbP = await sbGet("participants");
        if (dbP && dbP.length > 0) {
          const dbPort = await sbGet("portfolios");
          setParticipants(prev => prev.map(p => {
            const db   = dbP.find(d => d && (d.name === p.name || d.id === p.name.toLowerCase()));
            const port = (dbPort||[]).filter(pt => pt && pt.user_id === p.name.toLowerCase()).map(pt => ({ team: pt.team_id, slot: pt.slot_type, stage: pt.current_stage || "Group Stage", won: pt.won_stages || [], eliminated: pt.eliminated || false }));
            return db ? { ...p, teamPts: db.team_pts||0, predPts: db.pred_pts||0, challengePts: db.challenge_pts||0, bonusPts: db.bonus_pts||0, gloryRoadPts: db.glory_road_pts||0, portfolio: port.length > 0 ? port : p.portfolio } : p;
          }));
          // Update claimed teams
          if (dbPort && dbPort.length > 0) {
            const contenders = dbPort.filter(p => p && p.slot_type === "contender").map(p => p.team_id);
            const underdogs  = dbPort.filter(p => p && p.slot_type === "underdog").map(p => p.team_id);
            setClaimedTeams({ contenders, underdogs });
          }
        }
        if (!currentUser) return;
        const dbM = await sbGet("matches", "order=kickoff.asc");
        if (dbM && dbM.length > 0) {
          setMatches(dbM.filter(m => m && m.id).map(m => ({
            id: m.id, home: m.home_id||"tbd", away: m.away_id||"tbd",
            stage: m.stage||"Group Stage", date: m.match_date||"",
            kickoff: m.kickoff||null, status: m.status||"open",
            homeScore: m.home_score != null ? m.home_score : null,
            awayScore: m.away_score != null ? m.away_score : null,
            notes: m.notes || null,
            winner: m.winner || null,
          })));
        }
      } catch(e) { console.warn("Poll error:", e); }
    };
    poll(); // run immediately
    const interval = setInterval(poll, 10000); // every 10 seconds
    return () => clearInterval(interval);
  }, [currentUser]);

  // ── AUTO-LOCK PREDICTIONS AT KICK-OFF ────────────────────────
  useEffect(() => {
    const interval = setInterval(() => {
      const now = new Date();
      setMatches(prev => prev.map(m => {
        if (!m.kickoff || m.status !== "open") return m;
        const ko = new Date(m.kickoff);
        if (now >= ko) return { ...m, status: "locked" };
        return m;
      }));
    }, 30000);
    return () => clearInterval(interval);
  }, []);

  // ── HANDLERS ─────────────────────────────────────────────────

  const handleOnboardingComplete = async (name, portfolio) => {
    const userId = name.toLowerCase();
    // Save portfolio to Supabase
    for (const pt of portfolio) {
      const team = getTeam(pt.team);
      await sbUpsert("portfolios", {
        user_id:    userId,
        team_id:    pt.team,
        team_name:  team.name,
        slot_type:  pt.slot,
        multiplier: SLOT_MULT[pt.slot] || 1,
      });
    }
    setParticipants(prev => prev.map(p => p.name === name ? { ...p, portfolio } : p));
    setClaimedTeams(prev => ({
      contenders: [...prev.contenders, ...portfolio.filter(pt => pt.slot === "contender").map(pt => pt.team)],
      underdogs:  [...prev.underdogs,  ...portfolio.filter(pt => pt.slot === "underdog").map(pt => pt.team)],
    }));
    // No localStorage needed - name picker handles login each time
    setCurrentUser(name);
    sendChat("🎉 *" + name + " has joined the competition!*\nTheir squad is locked in — let the games begin! ⚽");
  };

  const handleSavePrediction = async (matchId, outcome) => {
    const userId = currentUser.toLowerCase();
    await sbUpsert("predictions", { user_id: userId, match_id: matchId, outcome, points_earned: 0 });
    setPredictions(prev => ({ ...prev, [matchId]: { outcome, pts: 0 } }));
  };

  const handleRecordResult = async (matchId, homeScore, awayScore, stage) => {
    // Update match
    await sbUpdate("matches", "id=eq." + matchId, { status: "completed", home_score: homeScore, away_score: awayScore });
    setMatches(prev => prev.map(m => m.id === matchId ? { ...m, status: "completed", homeScore, awayScore } : m));

    const match        = matches.find(m => m.id === matchId);
    if (!match) return;
    const actualOutcome = homeScore > awayScore ? "home" : awayScore > homeScore ? "away" : "draw";
    const h             = getTeam(match.home), a = getTeam(match.away);
    let   chatMsg       = "⚽ *FULL TIME!*\n*" + h.name + " " + homeScore + "–" + awayScore + " " + a.name + "*\n\n";

    // Score predictions
    const dbPreds = await sbGet("predictions", "match_id=eq." + matchId + "&points_earned=eq.0");
    for (const pred of (dbPreds || [])) {
      const correct = pred.outcome === actualOutcome;
      if (correct) {
        await sbUpdate("predictions", "user_id=eq." + pred.user_id + "&match_id=eq." + matchId, { points_earned: 20 });
        const p = participants.find(p => p.name.toLowerCase() === pred.user_id);
        if (p) {
          const newPts = (p.predPts || 0) + 20;
          await sbUpdate("participants", "id=eq." + pred.user_id, { pred_pts: newPts });
          setParticipants(prev => prev.map(pp => pp.name.toLowerCase() === pred.user_id ? { ...pp, predPts: newPts } : pp));
          chatMsg += "✅ " + p.name + " *+20 pts* (correct pick)\n";
        }
      }
    }

    // Team progression points
    const winnerId = actualOutcome === "home" ? match.home : actualOutcome === "away" ? match.away : null;
    const teamsToAward = stage === "Group Stage" ? [match.home, match.away] : winnerId ? [winnerId] : [];
    const basePts = STAGE_PTS[stage] || 0;
    if (basePts > 0) {
      chatMsg += "\n📈 *Team Points:*\n";
      for (const teamId of teamsToAward) {
        const dbPort = await sbGet("portfolios", "team_id=eq." + teamId);
        for (const port of (dbPort || [])) {
          const mult = port.multiplier || 1;
          const pts  = basePts * mult;
          const p    = participants.find(pp => pp.name.toLowerCase() === port.user_id);
          if (p && pts > 0) {
            const newTeamPts = (p.teamPts || 0) + pts;
            await sbUpdate("participants", "id=eq." + port.user_id, { team_pts: newTeamPts });
            await sbInsert("points_log", { user_id: port.user_id, pts, reason: getTeam(teamId).name + " " + stage + " (" + basePts + "x" + mult + ")" });
            setParticipants(prev => prev.map(pp => pp.name.toLowerCase() === port.user_id ? { ...pp, teamPts: newTeamPts } : pp));
            chatMsg += "⭐ " + p.name + " *+" + pts + " pts* (" + getTeam(teamId).name + " " + basePts + "×" + mult + ")\n";
          }
        }
      }
    }

    // Updated standings
    const updated = await sbGet("participants");
    if (updated && updated.length > 0) {
      const sorted = [...updated].sort((a, b) => (b.team_pts + b.pred_pts + b.challenge_pts + b.bonus_pts) - (a.team_pts + a.pred_pts + a.challenge_pts + a.bonus_pts));
      chatMsg += "\n📊 *Standings:*\n";
      const medals = ["🥇", "🥈", "🥉", "4️⃣", "5️⃣"];
      sorted.slice(0, 5).forEach((p, i) => {
        const tot = (p.team_pts || 0) + (p.pred_pts || 0) + (p.challenge_pts || 0) + (p.bonus_pts || 0);
        chatMsg += medals[i] + " " + p.name + " — *" + tot + " pts*\n";
      });
    }
    sendChat(chatMsg);
  };

  const handleAwardBonus = async (name, pts, reason) => {
    const p = participants.find(pp => pp.name === name);
    if (!p) return;
    const newBonus = (p.bonusPts || 0) + pts;
    await sbUpdate("participants", "id=eq." + name.toLowerCase(), { bonus_pts: newBonus });
    await sbInsert("points_log", { user_id: name.toLowerCase(), pts, reason: "Bonus: " + reason });
    setParticipants(prev => prev.map(pp => pp.name === name ? { ...pp, bonusPts: newBonus } : pp));
    sendChat("🎁 *Bonus Points!*\n*" + name + "* received *+" + pts + " pts*\nReason: " + reason);
  };

  const handleAdvanceTeam = async (teamId, stage) => {
    const team  = getTeam(teamId);
    const isElim = stage === "Eliminated";
    const dbPort = await sbGet("portfolios", "team_id=eq." + teamId);
    if (!dbPort || dbPort.length === 0) return;

    if (!isElim) {
      const basePts = STAGE_PTS[stage] || 0;
      for (const port of dbPort) {
        const mult = port.multiplier || 1;
        const pts  = basePts * mult;
        const p    = participants.find(pp => pp.name.toLowerCase() === port.user_id);
        // Update portfolio stage tracking
        const currentWon = port.won_stages || [];
        const newWon = currentWon.includes(stage) ? currentWon : [...currentWon, stage];
        await sbUpdate("portfolios", "id=eq." + port.id, {
          current_stage: stage,
          won_stages: newWon,
          eliminated: false,
        });
        if (p && pts > 0) {
          const newPts = (p.teamPts || 0) + pts;
          await sbUpdate("participants", "id=eq." + port.user_id, { team_pts: newPts });
          await sbInsert("points_log", { user_id: port.user_id, pts, reason: team.name + " reached " + stage });
          setParticipants(prev => prev.map(pp => pp.name.toLowerCase() === port.user_id ? {
            ...pp,
            teamPts: newPts,
            portfolio: (pp.portfolio || []).map(pt => pt.team === teamId ? { ...pt, stage, won: newWon, eliminated: false } : pt)
          } : pp));
        }
      }
      const owner = participants.find(p => p.name.toLowerCase() === dbPort[0].user_id);
      sendChat("🏆 *" + team.name + " advance to the " + stage + "!*\n" + (owner ? "⭐ " + owner.name + " earns points! (" + (STAGE_PTS[stage] || 0) + " × " + dbPort[0].multiplier + "×)" : ""));
    } else {
      for (const port of dbPort) {
        await sbUpdate("portfolios", "id=eq." + port.id, {
          eliminated: true,
        });
        setParticipants(prev => prev.map(pp => pp.name.toLowerCase() === port.user_id ? {
          ...pp,
          portfolio: (pp.portfolio || []).map(pt => pt.team === teamId ? { ...pt, eliminated: true } : pt)
        } : pp));
      }
      const owner = participants.find(p => p.name.toLowerCase() === dbPort[0].user_id);
      sendChat("💀 *" + team.name + " are ELIMINATED!*\n" + (owner ? owner.name + "'s " + team.name + " are out." : ""));
    }
  };

  const handleAddChallengePoints = async (pts) => {
    if (!currentUser || pts <= 0) return;
    const p = participants.find(pp => pp.name === currentUser);
    if (!p) return;
    const newPts = (p.challengePts || 0) + pts;
    await sbUpdate("participants", "id=eq." + currentUser.toLowerCase(), { challenge_pts: newPts });
    setParticipants(prev => prev.map(pp => pp.name === currentUser ? { ...pp, challengePts: newPts } : pp));
  };

  // ── RENDER ───────────────────────────────────────────────────

  const NAV = [
    { id: "dashboard",   icon: "🏠", label: "Home"      },
    { id: "leaderboard", icon: "📊", label: "Standings"  },
    { id: "myteams",     icon: "👕", label: "My Teams"   },
    { id: "predictions", icon: "🎯", label: "Predict"    },
    { id: "challenge",   icon: "🎮", label: "Challenge", badge: true },
    { id: "calendar",    icon: "📅", label: "Calendar"   },
    { id: "bracket",     icon: "🏆", label: "Bracket"    },
    { id: "gloryroad",   icon: "⭐", label: "Glory Road" },
    ...(isAdmin ? [{ id: "admin", icon: "⚙️", label: "Admin" }] : []),
  ];

  // Show How To Play FIRST on every new device/browser before anything else
  if (showHowTo) return (
    <React.Fragment>
      <style>{CSS}</style>
      <HowToPlay onDone={() => {
        try { localStorage.setItem("wc2026_howto_seen", "1"); } catch(e) {}
        setShowHowTo(false);
      }} />
    </React.Fragment>
  );

  if (loading) return (
    <React.Fragment>
      <style>{CSS}</style>
      <div style={{ minHeight: "100vh", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", background: "var(--bg)", gap: 20 }}>
        <div style={{ fontSize: 72, animation: "float 2s ease infinite" }}>⚽</div>
        <div style={{ fontFamily: "var(--fd)", fontSize: 32, color: "var(--navy)", letterSpacing: 2 }}>LOADING...</div>
        <div style={{ color: "var(--muted)", fontWeight: 700, fontSize: 14 }}>Connecting to competition</div>
        <div style={{ width: 200, height: 6, background: "var(--border)", borderRadius: 3, overflow: "hidden", marginTop: 8 }}>
          <div style={{ height: "100%", background: "var(--coral)", borderRadius: 3, animation: "loadbar 1.5s ease infinite" }} />
        </div>
      </div>
    </React.Fragment>
  );

  // HowToPlay handled above before loading screen

  if (!currentUser) return (
    <React.Fragment>
      <style>{CSS}</style>
      <NamePicker
        participants={participants}
        onSelect={async (name) => {
          // Check if this person has already onboarded
          const dbPort = await sbGet("portfolios", "user_id=eq." + name.toLowerCase());
          if (dbPort && dbPort.length > 0) {
            // Already onboarded — load their data and go to dashboard
            const dbPred = await sbGet("predictions", "user_id=eq." + name.toLowerCase());
            if (dbPred && dbPred.length > 0) {
              const predMap = {};
              dbPred.forEach(p => { predMap[p.match_id] = { outcome: p.outcome, pts: p.points_earned || 0 }; });
              setPredictions(predMap);
            }
            setCurrentUser(name);
          } else {
            // Not onboarded yet — go through onboarding
            setCurrentUser("__onboarding__" + name);
          }
        }}
      />
    </React.Fragment>
  );

  // Onboarding flow for new users
  if (currentUser && currentUser.startsWith("__onboarding__")) {
    const realName = currentUser.replace("__onboarding__", "");
    return (
      <React.Fragment>
        <style>{CSS}</style>
        <Onboarding
          whoOverride={realName}
          onComplete={handleOnboardingComplete}
          claimedTeams={claimedTeams}
          eliteAssign={eliteAssign}
        />
      </React.Fragment>
    );
  }

  const renderPage = () => {
    switch (page) {
      case "dashboard":   return <Dashboard   user={currentUser} participants={participants} matches={matches} setPage={setPage} showToast={showToast} />;
      case "leaderboard": return <Leaderboard user={currentUser} participants={participants} />;
      case "myteams":     return <MyTeams     user={currentUser} participants={participants} />;
      case "predictions": return <Predictions user={currentUser} matches={matches} predictions={predictions} onSavePrediction={handleSavePrediction} showToast={showToast} />;
      case "challenge":   return <Challenge   user={currentUser} participants={participants} showToast={showToast} onAddChallengePoints={handleAddChallengePoints} />;
      case "calendar":    return <Calendar    matches={matches} />;
      case "bracket":     return <Bracket     matches={matches} />;
      case "gloryroad":    return <Knockout    user={currentUser} matches={matches} participants={participants} showToast={showToast} />;
      case "admin":       return <AdminPanel  user={currentUser} participants={participants} matches={matches} showToast={showToast} onRecordResult={handleRecordResult} onAwardBonus={handleAwardBonus} onAdvanceTeam={handleAdvanceTeam} />;
      default:            return <Dashboard   user={currentUser} participants={participants} matches={matches} setPage={setPage} showToast={showToast} />;
    }
  };

  return (
    <React.Fragment>
      <style>{CSS}</style>
      <Blobs />
      <div className="app" style={{ position: "relative", zIndex: 1 }}>
        <div className="sidebar">
          <div className="sb-logo">⚽<br />WC<br />2026</div>
          {NAV.map(item => (
            <div key={item.id} className={"ni " + (page === item.id ? "on" : "")} onClick={() => setPage(item.id)}>
              <span>{item.icon}</span>
              {item.badge && page !== item.id && <div style={{ position: "absolute", top: 7, right: 7, width: 10, height: 10, background: "var(--yellow)", borderRadius: "50%", border: "2px solid var(--navy)" }} />}
              <div className="tip">{item.label}</div>
            </div>
          ))}
        </div>
        <div className="main">{renderPage()}</div>
        <div className="mnav">
          {NAV.map(item => (
            <div key={item.id} className={"mni " + (page === item.id ? "on" : "")} onClick={() => setPage(item.id)}>
              <div className="ico">{item.icon}</div>
              <div>{item.label}</div>
            </div>
          ))}
        </div>
        {toast && <Toast msg={toast} onClose={() => setToast(null)} />}
      </div>
    </React.Fragment>
  );
}
